inline const doom_stock_skeleton *doom_stock_skeleton_for(const char *name, int w, int h, const unsigned char *pixels)
{
    for (const doom_stock_skeleton &s : doom_stock_skeleton_table) {
        if (!s.name || strcmp(s.name, name) || s.width != w || s.height != h) continue;
        unsigned hash = 2166136261u;
        for (size_t i = 0; i < (size_t)w * h * 2; ++i) hash = (hash ^ pixels[i]) * 16777619u;
        return hash == s.hash ? &s : nullptr;
    }
    return nullptr;
}

